/**
 * 거울 효과 (SRS-RHB-020): the healthy half of the face reflected over the affected half, so both sides seem to move
 * together, as in the Mirror Effect Plus Protocol (MEPP; randomised trial in acute severe Bell's palsy, Clinical
 * Rehabilitation 2022). The mirror line is the upper face's rigid midline (forehead and nasal dorsum): the lips and chin
 * are pulled to the healthy side in a palsy and would tilt it. The healthy half is fitted to the affected half's outline
 * (mirrorMap), so a slightly turned head still lines up.
 */
import { CONTOURS, otherSide, type FrameObservation, type Side, type Vec2 } from '../../core';
import { MIRROR_PAIRS } from '../../core/landmarks';

/** Forehead and nasal dorsum: midline points that a palsy does not pull aside. */
const MIRROR_MIDLINE: readonly number[] = [10, 151, 9, 8, 168, 6, 197, 195, 5, 4];
const OVAL = CONTOURS.faceOval!;
const CHIN = 152;
const TOP = 10;

/** One side's half of the face outline, forehead top to chin (faceOval runs 10 → patient's left → 152 → right → 10). */
function halfOval(side: Side): readonly number[] {
  const k = OVAL.indexOf(CHIN);
  return side === 'left' ? OVAL.slice(0, k + 1) : [...OVAL.slice(k)].reverse();
}

export interface Line {
  /** A point on the line and its unit direction. */
  p: Vec2;
  u: Vec2;
}

/** Least-squares line through the midline points (principal axis), in pixels. */
export function mirrorLine(px: readonly Vec2[]): Line {
  const pts = MIRROR_MIDLINE.map((i) => px[i]!);
  const cx = pts.reduce((s, q) => s + q.x, 0) / pts.length;
  const cy = pts.reduce((s, q) => s + q.y, 0) / pts.length;
  let sxx = 0;
  let sxy = 0;
  let syy = 0;
  for (const q of pts) {
    sxx += (q.x - cx) ** 2;
    sxy += (q.x - cx) * (q.y - cy);
    syy += (q.y - cy) ** 2;
  }
  const theta = 0.5 * Math.atan2(2 * sxy, sxx - syy);
  return { p: { x: cx, y: cy }, u: { x: Math.cos(theta), y: Math.sin(theta) } };
}

/** Canvas transform (a, b, c, d, e, f) of the reflection over the line: x' = a x + c y + e, y' = b x + d y + f. */
export function reflection(l: Line): [number, number, number, number, number, number] {
  const { x: ux, y: uy } = l.u;
  const a = ux * ux - uy * uy;
  const b = 2 * ux * uy;
  const d = -a;
  const { x: px, y: py } = l.p;
  return [a, b, b, d, px - (a * px + b * py), py - (b * px + d * py)];
}

/** Bony outline pairs (face oval) and the inner eye corners: right index, left index. Lips and brows droop in a palsy. */
const FIT_PAIRS = MIRROR_PAIRS.filter(([r]) => OVAL.includes(r) || r === 133);

/**
 * The map that puts the healthy half where the affected half is: a least-squares affine transform taking the healthy
 * side's outline points onto their partners and keeping the midline in place. A plain reflection would show the nearer
 * half too big when the head is turned a little; this one follows the narrower or wider half. Falls back to the
 * reflection if the fit is poor or not a mirror image.
 */
export function mirrorMap(px: readonly Vec2[], affected: Side, l: Line = mirrorLine(px)): [number, number, number, number, number, number] {
  const src: Vec2[] = [];
  const dst: Vec2[] = [];
  const w: number[] = [];
  for (const [r, lf] of FIT_PAIRS) {
    const [from, to] = affected === 'left' ? [r, lf] : [lf, r];
    src.push(px[from]!);
    dst.push(px[to]!);
    w.push(1);
  }
  for (const i of MIRROR_MIDLINE) {
    src.push(px[i]!);
    dst.push(px[i]!);
    w.push(2);
  }
  // Normal equations of x' = a x + c y + e and y' = b x + d y + f (shared 3 × 3 matrix).
  const N = [0, 0, 0, 0, 0, 0, 0, 0, 0];
  const bx = [0, 0, 0];
  const by = [0, 0, 0];
  src.forEach((q, k) => {
    const v = [q.x, q.y, 1];
    for (let i = 0; i < 3; i++) {
      for (let j = 0; j < 3; j++) N[3 * i + j]! += w[k]! * v[i]! * v[j]!;
      bx[i]! += w[k]! * v[i]! * dst[k]!.x;
      by[i]! += w[k]! * v[i]! * dst[k]!.y;
    }
  });
  // Cramer's rule on the symmetric 3 × 3 system.
  const det3 = (m: readonly number[]) =>
    m[0]! * (m[4]! * m[8]! - m[5]! * m[7]!) - m[1]! * (m[3]! * m[8]! - m[5]! * m[6]!) + m[2]! * (m[3]! * m[7]! - m[4]! * m[6]!);
  const d = det3(N);
  const solve = (b: readonly number[]): number[] | null =>
    Math.abs(d) < 1e-9 ? null : [0, 1, 2].map((c) => det3(N.map((v, k) => (k % 3 === c ? b[Math.floor(k / 3)]! : v))) / d);
  const X = solve(bx);
  const Y = solve(by);
  const fallback = reflection(l);
  if (!X || !Y) return fallback;
  const m: [number, number, number, number, number, number] = [X[0]!, Y[0]!, X[1]!, Y[1]!, X[2]!, Y[2]!];
  // A mirror image flips orientation; and the fit must land the outline near its partners (within a tenth of the eyes' spacing).
  const ipd = Math.hypot(px[33]!.x - px[263]!.x, px[33]!.y - px[263]!.y);
  const err =
    src.slice(0, FIT_PAIRS.length).reduce((e, q, k) => {
      const t = applyTransform(m, q);
      return e + Math.hypot(t.x - dst[k]!.x, t.y - dst[k]!.y);
    }, 0) / FIT_PAIRS.length;
  return m[0] * m[3] - m[1] * m[2] < 0 && err < 0.1 * ipd ? m : fallback;
}

/** A point through the transform (for tests and the seam). */
export const applyTransform = (m: readonly number[], q: Vec2): Vec2 => ({
  x: m[0]! * q.x + m[2]! * q.y + m[4]!,
  y: m[1]! * q.x + m[3]! * q.y + m[5]!,
});

const project = (l: Line, q: Vec2): Vec2 => {
  const t = (q.x - l.p.x) * l.u.x + (q.y - l.p.y) * l.u.y;
  return { x: l.p.x + t * l.u.x, y: l.p.y + t * l.u.y };
};

/**
 * Head turn (deg) up to which the reflection is drawn, and past which it stops: turned away, the far half's outline lies
 * on the background and its reflection would show it. Two limits so it does not flicker at one.
 */
export const MIRROR_YAW_ON = 8;
export const MIRROR_YAW_OFF = 12;

/** Whether to draw the reflection now, given whether it was drawn on the last frame. */
export const mirrorFrontal = (wasOn: boolean, yawDeg: number): boolean => Math.abs(yawDeg) <= (wasOn ? MIRROR_YAW_OFF : MIRROR_YAW_ON);

/** The outline is drawn this much in towards the mirror line: the face oval runs a little past the cheek, into the background. */
const RING_INSET = 0.97;

/** The healthy half's outline closed along the mirror line, so its reflection meets the healthy half without a gap. */
export function healthyHalf(px: readonly Vec2[], affected: Side, l: Line): Vec2[] {
  const ring = halfOval(otherSide(affected)).map((i) => {
    const q = px[i]!;
    const o = project(l, q);
    return { x: o.x + (q.x - o.x) * RING_INSET, y: o.y + (q.y - o.y) * RING_INSET };
  });
  return [project(l, px[TOP]!), ...ring, project(l, px[CHIN]!)];
}

/** Landmarks in video pixels, or null without a full face. */
const pixels = (obs: FrameObservation): Vec2[] | null =>
  obs.landmarks.length < 468 * 3
    ? null
    : Array.from({ length: 468 }, (_, i) => ({ x: obs.landmarks[3 * i]! * obs.width, y: obs.landmarks[3 * i + 1]! * obs.height }));

/** Draws the reflected healthy half over the affected half of the live frame (canvas in video pixels). False without a face. */
export function drawMirrorHalf(ctx: CanvasRenderingContext2D, obs: FrameObservation, video: CanvasImageSource, affected: Side): boolean {
  const px = pixels(obs);
  if (!px) return false;
  const l = mirrorLine(px);
  const poly = healthyHalf(px, affected, l);
  ctx.save();
  ctx.setTransform(...mirrorMap(px, affected, l));
  ctx.beginPath();
  poly.forEach((q, k) => (k ? ctx.lineTo(q.x, q.y) : ctx.moveTo(q.x, q.y)));
  ctx.closePath();
  // The path is taken in the mapped space, so the clip falls on the affected side.
  ctx.clip();
  ctx.drawImage(video, 0, 0, obs.width, obs.height);
  ctx.restore();
  return true;
}
