/** "검지·중지로 눈 안쪽을 — 고정" style line for a group of contacts (same landmark merged). */
function handLine(cs: Contact[]): string {
  const groups: { labels: string[]; land: string; act: string }[] = [];
  for (const c of cs) {
    const g = groups.find((x) => x.land === c.land && x.act === c.act);
    const label = c.intraoral ? `${c.label}(입안)` : c.label;
    if (g) g.labels.push(label);
    else groups.push({ labels: [label], land: c.land, act: c.act });
  }
  return groups.map((g) => `${g.labels.join('·')}: ${g.land} — ${g.act}`).join(' / ');
}

interface CoachView {
  state: CoachState;
  progress: number;
  healthyLoad: number;
  held: number;
  reps: number;
  /** A small movement on the affected side with the healthy side still (SRS-RHB-019). */
  micro?: boolean;
  /** The region that must stay still: its movement and grade (SRS-RHB-022). */
  synkIndex?: number;
  synkLevel?: SynkLevel;
  /** Affected / healthy right now; null while the healthy side rests. */
  ratio?: number | null;
}

/** What to move, said the way the guide draws it (yellow dashed goal). */
const GUIDE_START: Record<LiveTaskId, string> = {
  brow: '눈썹을 노란 점선까지 천천히 올려 보세요',
  eyeClose: '윗눈꺼풀을 노란 선까지 살며시 내려 보세요',
  smile: '입꼬리를 노란 원까지 천천히 당겨 보세요',
  snarl: '콧방울을 노란 원까지 살짝 올려 보세요',
  pucker: '입꼬리를 노란 원 쪽으로 오므려 보세요',
  cheekPuff: '입술을 다문 채 볼에 공기를 채워, 볼 선을 노란 점선까지 부풀려 보세요',
};

/** The region that must stay still in words (SRS-RHB-022). */
const STILL_NAME = { eye: '눈', mouth: '입꼬리' } as const;
const SYNK_GRADE = ['없음', '약함', '중간', '강함'] as const;

function coachText(task: LiveTaskId, c: CoachView): string {
  switch (c.state) {
    case 'rest':
      return c.micro ? '아주 작은 움직임이 보여요. 좋아요, 천천히 조금 더' : GUIDE_START[task];
    case 'move':
      return c.progress >= 0.8 ? '거의 다 왔어요. 조금만 더' : '조금 더, 노란 목표까지';
    case 'good':
      return c.held >= 1 ? '잘했어요. 천천히 풀어 주세요' : '좋아요! 그대로 유지하세요';
    case 'tooStrong':
      return '건강한 쪽 힘을 빼고 작게 움직이세요';
    case 'synk':
      return synkText(task, c.synkLevel || 1);
  }
}

/** One tip after a guided exercise, for what went wrong most (SRS-RHB-018). */
function qualityTip(q: BioQuality): string | null {
  if (q.synk > 0 && q.synk >= q.tooStrong)
    return '다른 곳이 같이 움직이면 동작을 더 작고 천천히 하세요. 같이 움직이는 곳을 거울로 보며 멈추는 연습이 도움이 됩니다.';
  if (q.tooStrong > 0) return '건강한 쪽은 힘을 빼고, 마비된 쪽만 천천히 움직여 보세요.';
  if (q.reps === 0 && q.microEvents)
    return '목표에는 아직 못 미쳤지만 마비된 쪽에서 아주 작은 움직임이 보였어요. 회복 초기에는 이런 작은 움직임부터 시작합니다.';
  if (q.reps === 0) return '목표가 멀면 무리하지 말고 되는 만큼만 하세요. 다음 평가를 하면 목표가 다시 맞춰집니다.';
  return null;
}

/** What the live guide counted in the exercise just finished. */
function QualityLine({ q }: { q: BioQuality | null }) {
  if (!q || q.attempts === 0) return null;
  const tip = qualityTip(q);
  return (
    <div class="stack" style={{ gap: '4px' }}>
      <p class="small" style={{ margin: 0 }}>
        실시간 안내: 시도 {q.attempts}회 중 <b>목표 유지 {Math.min(q.reps, q.attempts)}회</b>
        {q.tooStrong > 0 && ` · 건강한 쪽 힘 과다 ${q.tooStrong}회`}
        {q.synk > 0 && ` · 다른 곳 같이 움직임 ${q.synk}회`}
        {!!q.microEvents && ` · 작은 움직임 ${q.microEvents}회`}
      </p>
      {tip && (
        <p class="xsmall ink2" style={{ margin: 0 }}>
          {tip}
        </p>
      )}
    </div>
  );
}

function goalText(plan: GuidePlan): string {
  const pct = (v: number) => `${Math.round(v * 100)}%`;
  if (plan.source === 'default') return '목표는 기본값입니다. 평가를 하면 내 움직임에 맞춰집니다.';
  return plan.task === 'eyeClose'
    ? `목표: 눈을 ${pct(plan.goal)}까지 감기 (지난 평가 ${pct(plan.lastRatio ?? 0)}에서 한 걸음 더).`
    : `목표: 건강한 쪽 편안한 움직임의 ${pct(plan.goal)}까지 (지난 평가 ${pct(plan.lastRatio ?? 0)}에서 한 걸음 더).`;
}
const PREF_KEY = 'fsr.view.v1';
/**
 * Live point tracking (SRS-RHB-026): the guide measures tracked points, as the assessment does (detections alone read a
 * weak side high, most in severe palsy). Above this smoothed cost per frame (ms) the phone is too slow: the guide goes
 * back to detections and shows no live % except for eye closure. Provisional until measured on phones.
 */
const LIVE_TRACK_BUDGET_MS = 40;

interface Prefs {
  mode: '2d' | '3d' | 'video';
  showMuscle: boolean;
  callouts: boolean;
  ghostHands: boolean;
  loupe: boolean;
  riggedHands: boolean;
  holdSec: number | null;
  speed: number;
}

function loadPrefs(): Prefs {
  const d: Prefs = {
    mode: 'video', // rendered clip where one exists, otherwise the 2D illustration
    showMuscle: true,
    callouts: true,
    ghostHands: true,
    loupe: true,
    riggedHands: true,
    holdSec: null,
    speed: 1,
  };
  try {
    return { ...d, ...(JSON.parse(localStorage.getItem(PREF_KEY) ?? '{}') as Partial<Prefs>) };
  } catch {
    return d;
  }
}

/** Breathing pacer in place of the camera (SRS-RHB-025): a circle that grows on the in-breath and shrinks on the out-breath. */
function BreathPacer({ scene, running }: { scene: Scene; running: boolean }) {
  const k = !running
    ? 0.35
    : scene.phase.key === 'inhale'
      ? 0.35 + 0.65 * scene.phaseT
      : scene.phase.key === 'exhale'
        ? 1 - 0.65 * scene.phaseT
        : 0.35;
  return (
    <div class="card">
      <h3>숨 박자</h3>
      <div class="breath-pacer" aria-live="polite">
        <div class="breath-circle" style={{ transform: `scale(${k.toFixed(3)})` }} />
        <div class="breath-text">
          {running ? (
            <>
              <b>{scene.phase.key === 'inhale' ? '들이마시기' : '내쉬기'}</b>
              <span class="tabular"> {Math.max(1, Math.ceil(scene.remaining))}</span>
            </>
          ) : (
            '‘따라하기 시작’을 누르면 숨 박자가 나옵니다'
          )}
        </div>
      </div>
      <p class="xsmall muted">원이 커질 때 코로 4초 들이마시고, 작아질 때 입으로 6초 길게 내쉽니다. 얼굴 힘을 빼고 어깨를 내립니다.</p>
    </div>
  );
}

export interface RoutineInfo {
  index: number;
  count: number;
  nextTitle: string | null;
  /** The item's place in today's order ('1순위 · 입', planTag). */
  tag?: string;
}

/** Today's plan played back-to-back: #/routine/<index>. */
export function RoutinePlayer({ index }: { index: number }) {
  const { plan } = useTodayPlan();
  const items = plan.items;
  const i = Math.max(0, Math.min(items.length - 1, index));
  const item = items[i];
  if (!item) return <ExercisePlayer id="" />;
  return (
    <ExercisePlayer
      key={`routine-${i}`}
      id={item.exercise.id}
      routine={{ index: i, count: items.length, nextTitle: items[i + 1]?.exercise.title ?? null, tag: planTag(item, plan.phase) }}
    />
  );
}

export function ExercisePlayer({ id, routine }: { id: string; routine?: RoutineInfo }) {
  const { profile } = useApp();
  const ex = exerciseById(id);
  const [prefs, setPrefs] = useState<Prefs>(loadPrefs);
  const setPref = <K extends keyof Prefs>(k: K, v: Prefs[K]) => {
    const next = { ...prefs, [k]: v };
    setPrefs(next);
    try {
      localStorage.setItem(PREF_KEY, JSON.stringify(next));
    } catch {
      /* private mode */
    }
  };
  const program = ex ? programFor(ex.id) : undefined;
  const { plan: today } = useTodayPlan();
  // Personal dose from earlier answers (쉬움·적당·힘듦·불편), fixed for this exercise while it is on screen.
  const dose = useMemo(() => (ex ? doseFor(ex, getState().rehab, today.phase) : null), [ex?.id]);
  const manualHold = !!(program && prefs.holdSec);
  const plan = ex ? planFor(ex, { ...(dose?.opts ?? {}), ...(manualHold ? { holdSec: prefs.holdSec! } : {}) }) : null;
  const [logId, setLogId] = useState<string | null>(null);
  const clock = useExerciseClock(plan?.total ?? 1);
  const [viewMode, setViewMode] = useState<'mirror' | 'clinical'>(profile?.viewMode ?? 'mirror');
  const [mirror, setMirror] = useState(false);
  // 거울 효과 (SRS-RHB-020): the healthy half reflected over the affected half (MEPP); the guide's marks are left out.
  const [halfMirror, setHalfMirror] = useState(false);
  const mirrorOn = useRef(false);
  const [calib, setCalib] = useState<'none' | 'collecting' | 'ready'>('none');
  const [coach, setCoach] = useState<CoachView | null>(null);
  const [saved, setSaved] = useState(false);
  const [quality, setQuality] = useState<BioQuality | null>(null);
  const [showSettings, setShowSettings] = useState(false);
  const refFrames = useRef<FrameObservation[]>([]);
  const restRef = useRef<RestReference | null>(null);
  const frameN = useRef(0);
  const lastCue = useRef('');
  const counter = useRef<RepCounter | null>(null);
  const coachState = useRef<CoachState>('rest');
  const coachMicro = useRef(false);
  const lastSpoken = useRef({ text: '', at: 0 });
  const sceneRef = useRef<Scene | null>(null);
  const lastMarks = useRef<{ marks: StretchMark[]; at: number } | null>(null);
  const [faceLost, setFaceLost] = useState(false);
  // Graded warning shown on the face and said once per rise (SRS-RHB-022); frames of a steady face before calibrating.
  const synkLevel = useRef<SynkLevel>(0);
  const synkSaid = useRef({ level: 0, at: 0 });
  const steady = useRef(0);
  const tracker = useRef<CaptureTracker | null>(null);
  const trackMs = useRef(0);
  const trackMode = useRef<'off' | 'on' | 'slow'>('off');
  const [liveTracking, setLiveTracking] = useState<'off' | 'on' | 'slow'>('off');
  const lastTracked = useRef<FrameObservation | null>(null);
  const voice = profile?.voiceGuide ?? true;
  const task = ex?.biofeedback;
  // Which live guide the camera mirror offers: movement targets (SRS-RHB-015), the stretch hands (SRS-RHB-016) or the
  // massage path (SRS-RHB-024). Breathing gets a pacer and eye care no camera (SRS-RHB-025).
  const guideKind: 'move' | 'stretch' | 'massage' | null = task
    ? 'move'
    : ex?.kind === 'stretch' && program
      ? 'stretch'
      : ex?.kind === 'massage'
        ? 'massage'
        : null;
  const aff = profile?.affectedSide ?? 'left';
  const healthy = otherSide(aff);
  // Detections alone read the weak side high except in eye closure (BENCH.md, own videos): the % needs tracking.
  const ratioShown = task === 'eyeClose' || liveTracking === 'on';

  // The live guide's targets: from the latest assessment that measured this movement (rehab/biofeedback.ts).
  const bioPlan = useMemo<GuidePlan | null>(() => {
    if (!task) return null;
    const scored = getState().sessions.filter((s) => s.analysis.scores);
    return guidePlan(task, scored[scored.length - 1]?.analysis ?? null, aff);
  }, [task, aff]);
  const cue = (text: string) => {
    const now = performance.now();
    const l = lastSpoken.current;
    if (now - l.at < 3500 || (l.text === text && now - l.at < 8000)) return;
    lastSpoken.current = { text, at: now };
    speak(text, voice);
  };

  const cam = useFaceCamera(
    mirror,
    (obs, q, src) => {
      if (!guideKind) return;
      // Calibrate by itself once the face has been steady half a second (no extra button; SRS-RHB-025).
      if (calib === 'none') {
        steady.current = q.ok ? steady.current + 1 : 0;
        if (steady.current >= 15) {
          steady.current = 0;
          refFrames.current = [];
          setCalib('collecting');
          speak(
            guideKind === 'move' ? '편안히 정면을 보세요. 기준 얼굴을 잽니다.' : '손을 내리고 정면을 보세요. 기준 얼굴을 잽니다.',
            voice,
          );
        }
        return;
      }
      if (calib === 'collecting' && q.ok) {
        refFrames.current.push(obs);
        if (refFrames.current.length >= 20) {
          restRef.current = buildRestReference(refFrames.current);
          counter.current = restRef.current && task && bioPlan ? new RepCounter(task, aff, bioPlan) : null;
          // The still face's own jitter: what a small movement has to stand out from (SRS-RHB-019).
          if (counter.current && restRef.current && task) {
            const ref = restRef.current;
            counter.current.setNoise(restNoise(refFrames.current.flatMap((o) => measureLive(task, ref, o) ?? [])));
          }
          setCalib(restRef.current ? 'ready' : 'none');
          // Track the task's points from this frame on (SRS-RHB-026).
          if (restRef.current && task) {
            const tk = new CaptureTracker();
            tk.setRef(src, obs);
            tracker.current = tk.ref ? tk : null;
            trackMs.current = 0;
            trackMode.current = tk.ref ? 'on' : 'off';
            setLiveTracking(trackMode.current);
          }
          if (restRef.current) {
            speak(
              guideKind === 'move'
                ? '준비되었습니다. 노란 목표까지 천천히 움직여 보세요.'
                : guideKind === 'massage'
                  ? '준비되었습니다. 주황 원을 따라 손가락을 움직이세요.'
                  : '준비되었습니다. 파란 원과 주황 원에 손가락을 대세요.',
              voice,
            );
            // The demo, the voice and the guide run on one timeline: start it if it is not running yet.
            if (plan && !clock.running && clock.get() < plan.total) clock.play();
          }
        }
        return;
      }
      if (guideKind === 'stretch' || guideKind === 'massage') {
        // A face hidden by the hands for over 1.5 s: ask to lower them so the guide can find the face again.
        const lost = !!lastMarks.current && performance.now() - lastMarks.current.at > 1500;
        if (lost !== faceLost) setFaceLost(lost);
        return;
      }
      if (!task || calib !== 'ready' || !restRef.current || !counter.current) return;
      let mobs = obs;
      const tk = tracker.current;
      if (tk && trackMode.current === 'on') {
        const t0 = performance.now();
        const g = tk.grab(src, obs);
        if (g) mobs = tk.track({ obs, gray: g }, liveTrackPoints(task));
        const ms = performance.now() - t0;
        trackMs.current = trackMs.current ? trackMs.current * 0.9 + ms * 0.1 : ms;
        if (trackMs.current > LIVE_TRACK_BUDGET_MS) {
          trackMode.current = 'slow';
          setLiveTracking('slow');
          mobs = obs;
        }
      }
      lastTracked.current = mobs;
      const v = measureLive(task, restRef.current, mobs);
      if (!v) return;
      const before = coachState.current;
      const now = performance.now();
      const c = counter.current.update(v, now / 1000);
      coachState.current = c.state;
      synkLevel.current = c.synkLevel;
      // The co-movement warning is said when it rises, and again every 6 s while it stays moderate or worse.
      const said = synkSaid.current;
      const rise = c.synkLevel > said.level;
      if (c.synkLevel === 0) said.level = 0;
      if (c.synkLevel > 0 && (rise || (c.synkLevel >= 2 && now - said.at > 6000))) {
        cue(synkText(task, c.synkLevel));
        synkSaid.current = { level: c.synkLevel, at: now };
      } else if (c.counted) cue('좋아요');
      else if (c.state !== before && c.state === 'tooStrong') cue('건강한 쪽 힘을 빼세요');
      else if (c.micro && !coachMicro.current) cue('작은 움직임이 보여요');
      coachMicro.current = c.micro;
      if (++frameN.current % 3 === 0 || c.counted || rise)
        setCoach({
          state: c.state,
          progress: c.progress,
          healthyLoad: c.healthyLoad,
          held: c.held,
          reps: c.reps,
          micro: c.micro,
          synkIndex: c.synkIndex,
          synkLevel: c.synkLevel,
          ratio: c.ratio,
        });
    },
    null,
    halfMirror
      ? null
      : // Drawn over the current frame: rest, now and goal of the moving points (ui/rehab/bioGuide.ts).
        task && bioPlan && calib === 'ready'
        ? (ctx, obs, q) => {
            if (!q.ok || !restRef.current) return;
            // The tracked points of the last frame (this frame's are tracked after it is drawn).
            const g = guideLines(task, restRef.current, lastTracked.current ?? obs, aff, bioPlan);
            if (!g) return;
            drawGuide(ctx, g, coachState.current, obs.width);
            drawStill(ctx, g.still, synkLevel.current, obs.width);
          }
        : guideKind === 'stretch' && calib === 'ready'
          ? (ctx, obs) => {
              const sc = sceneRef.current;
              if (!restRef.current || !sc || !sc.step || sc.hands.length === 0 || sc.approach <= 0) {
                lastMarks.current = null;
                return;
              }
              const now = performance.now();
              const m = stretchMarks(restRef.current, obs, aff, sc);
              if (m) lastMarks.current = { marks: m, at: now };
              // Hands over the face can lose it for a moment: keep the last position briefly.
              const show = m ?? (lastMarks.current && now - lastMarks.current.at < 1500 ? lastMarks.current.marks : null);
              if (show) drawStretch(ctx, show, obs.width);
            }
          : guideKind === 'massage' && calib === 'ready'
            ? (ctx, obs, q) => {
                const sc = sceneRef.current;
                if (!q.ok || !restRef.current || !sc) return;
                const m = massageMarks(restRef.current, obs, aff, sc);
                if (m) {
                  lastMarks.current = { marks: [], at: performance.now() };
                  drawMassage(ctx, m, obs.width);
                }
              }
            : null,
    halfMirror
      ? (ctx, obs, video, q) => {
          mirrorOn.current = mirrorFrontal(mirrorOn.current, q.pose.yaw);
          if (mirrorOn.current) drawMirrorHalf(ctx, obs, video, aff);
        }
      : null,
  );
  const bioLog = () => {
    if (!task || !bioPlan || !counter.current) return {};
    const { ratioMed, ...q } = counter.current.quality();
    const tracked = trackMode.current === 'on';
    // The exercise-time ratio only when it can be trusted (SRS-RHB-026/027).
    const keepRatio = ratioMed !== undefined && (tracked || task === 'eyeClose');
    return { bio: { task, goal: bioPlan.goal, source: bioPlan.source, ...q, tracked, ...(keepRatio ? { ratioMed } : {}) } };
  };
  useWakeLock(clock.running || mirror);

  useEffect(() => {
    if (clock.speed !== prefs.speed) clock.setSpeed(prefs.speed);
  }, [prefs.speed]);

  // Video mode only where a rendered clip exists; elsewhere the saved choice falls back to the 2D illustration.
  // The eye-care card is pictograms (drops, glasses, patch) that only the 2D view draws.
  // Stretches with a clip show only the clip for now (STRETCH_VIDEO_ONLY).
  const no3d = ex?.kind === 'eyecare';
  const videoOnly = STRETCH_VIDEO_ONLY && ex?.kind === 'stretch' && hasClips(ex.id);
  const stageMode = videoOnly
    ? 'video'
    : (prefs.mode === 'video' && !(ex && hasClips(ex.id))) || (prefs.mode === '3d' && no3d)
      ? '2d'
      : prefs.mode;
  const elapsed = clock.get();
  const scene = ex && plan ? sceneAt(ex, elapsed, plan) : null;
  sceneRef.current = scene;
  const doneNow = !!plan && elapsed >= plan.total;
  const [nextIn, setNextIn] = useState<number | null>(null);
  const goNext = () => {
    if (!routine) return;
    if (routine.index + 1 < routine.count) navigate(`/routine/${routine.index + 1}`);
    else navigate('/rehab');
  };

  // Routine: start on arrival (the user tapped "루틴 시작"), log on completion, then count down to the next item.
  useEffect(() => {
    if (routine && ex) clock.play();
  }, []);
  useEffect(() => {
    if (!routine || !doneNow || saved || !ex || !plan) return;
    setSaved(true);
    setQuality(counter.current?.quality() ?? null);
    void actions.logRehab(ex.id, Math.round(plan.total), { doseStep: dose?.step ?? 0, ...bioLog() }).then((l) => setLogId(l.id));
    if (routine.index + 1 < routine.count) {
      setNextIn(10);
      speak(`다음은 ${routine.nextTitle ?? ''}입니다. 10초 쉬세요.`, voice);
    } else speak('오늘 루틴을 모두 마쳤습니다.', voice);
  }, [doneNow]);
  useEffect(() => {
    if (nextIn === null) return;
    if (nextIn <= 0) {
      goNext();
      return;
    }
    const t = setTimeout(() => setNextIn(nextIn - 1), 1000);
    return () => clearTimeout(t);
  }, [nextIn]);

  // Voice cue on every phase change.
  useEffect(() => {
    if (!scene || !ex || !clock.running) return;
    const key = `${scene.stepIndex}:${scene.rep}:${scene.phase.key}`;
    if (key === lastCue.current) return;
    lastCue.current = key;
    if (scene.done) speak('잘하셨습니다.', voice);
    else if (scene.phase.key === 'prepare') speak(scene.step?.cue ?? ex.steps[0] ?? scene.phase.label, voice);
    else if (scene.phase.key === 'hold') speak(`${Math.round(scene.phase.dur)}초 유지`, voice);
    else if (scene.mode === 'eyecare') speak(ex.steps[scene.textStep] ?? '', voice);
    else speak(scene.phase.label, voice);
  });

  if (!ex || !plan || !scene) {
    return (
      <>
        <AppBar title="운동" onBack />
        <main class="main">
          <div class="card">운동을 찾을 수 없습니다.</div>
        </main>
      </>
    );
  }

  const finished = elapsed >= plan.total;
  const started = elapsed > 0;
  const step = scene.step;
  const stepStart = (i: number) => plan.blocks.find((b) => b.step === i)?.start ?? 0;
  const view2d = {
    affectedSide: aff,
    mirror: viewMode === 'mirror',
    showMuscle: prefs.showMuscle,
    callouts: prefs.callouts,
    ghostHands: prefs.ghostHands,
    riggedHands: prefs.riggedHands,
  };

  const complete = async () => {
    const log = await actions.logRehab(ex.id, Math.round(Math.min(elapsed, plan.total)) || ex.durationSec, {
      doseStep: dose?.step ?? 0,
      ...bioLog(),
    });
    setQuality(counter.current?.quality() ?? null);
    setSaved(true);
    setLogId(log.id);
  };

  return (
    <>
      <AppBar
        title={ex.title}
        sub={
          routine
            ? `오늘 루틴 ${routine.index + 1}/${routine.count} · ${routine.tag ? `${routine.tag} · ` : ''}${KIND_LABEL[ex.kind]}`
            : `${KIND_LABEL[ex.kind]} · ${ex.regions.map((r) => REGION_LABEL[r]).join('·')}`
        }
        onBack
      />
      <main class="main">
        {routine && (
          <div class="routine-bar" role="status">
            <div class="track">
              <div class="fill" style={{ width: `${((routine.index + (finished ? 1 : elapsed / plan.total)) / routine.count) * 100}%` }} />
            </div>
            <div class="row between xsmall">
              <span>
                루틴 {routine.index + 1}/{routine.count}
              </span>
              <span class="muted">{routine.nextTitle ? `다음: ${routine.nextTitle}` : '마지막 운동'}</span>
            </div>
          </div>
        )}
        {(dose?.caution || (dose?.reason && !manualHold)) && !finished && (
          <div class="card tight">
            {dose.caution && (
              <Notice tone="warn">
                <span class="small">{dose.caution}</span>
              </Notice>
            )}
            {dose.reason && !manualHold && (
              <Notice>
                <span class="small">{dose.reason}</span>
              </Notice>
            )}
          </div>
        )}
        {routine && finished && (
          <div class="card accent">
            {routine.index + 1 < routine.count ? (
              <>
                <h3>잘하셨습니다. 기록했어요.</h3>
                <p class="small ink2">
                  다음: <b>{routine.nextTitle}</b> — {nextIn ?? 0}초 뒤에 시작합니다. 잠시 얼굴 힘을 빼고 쉬세요.
                </p>
                <QualityLine q={quality} />
                <div class="row">
                  <button class="btn primary grow" onClick={goNext}>
                    <Icon name="play" /> 바로 다음 운동
                  </button>
                  <button class="btn" onClick={() => setNextIn(null)}>
                    여기서 멈추기
                  </button>
                </div>
              </>
            ) : (
              <>
                <h3>오늘 루틴을 모두 마쳤습니다</h3>
                <QualityLine q={quality} />
                <p class="small ink2">{routine.count}가지 운동을 기록했습니다. 내일도 같은 시간에 해 보세요.</p>
                <a class="btn primary block" href="#/">
                  홈으로
                </a>
              </>
            )}
            {logId && <FeelPrompt logId={logId} />}
          </div>
        )}
        <p class="ink2">{ex.summary}</p>

        <div class="card">
          {!videoOnly && (
            <Segmented
              label="보기 방식"
              value={stageMode}
              onChange={(m) => setPref('mode', m)}
              options={[
                ...(hasClips(ex.id) ? [{ value: 'video' as const, label: '영상' }] : []),
                { value: '2d' as const, label: '2D 일러스트' },
                ...(no3d ? [] : [{ value: '3d' as const, label: '3D 아바타' }]),
              ]}
            />
          )}
          <div class="fsr-wrap">
            <RehabStage
              ex={ex}
              plan={plan}
              clock={clock}
              mode={stageMode}
              view={view2d}
              loupe={prefs.loupe && stageMode === '2d'}
              onFail3D={() => setPref('mode', '2d')}
            />
            <div class="anim-hud">
              <span class={`chip ${scene.phase.key === 'hold' ? 'accent' : ''}`} aria-live="polite">
                {finished ? '끝' : started ? scene.phase.label : '시작을 누르세요'}
              </span>
              <span class="chip tabular">
                {scene.steps > 1 && `동작 ${scene.stepIndex + 1}/${scene.steps} · `}
                {Math.max(1, scene.rep)}/{scene.reps}
                {ex.kind === 'eyecare' ? '' : '회'}
              </span>
            </div>
            {started && !finished && ['hold', 'inhale', 'exhale', 'prepare'].includes(scene.phase.key) && (
              <div class="anim-count tabular">{Math.ceil(scene.remaining)}</div>
            )}
          </div>
          {step && (
            <div class="fsr-step">
              <b>
                {scene.steps > 1 ? `${scene.stepIndex + 1}. ` : ''}
                {step.title}
              </b>
              <dl class="howto">
                <dt>어디</dt>
                <dd>
                  {SIDE_LABEL[aff]}(마비 쪽) {MUSCLES[step.muscle].name}
                </dd>
                {handLine(step.contacts.filter((c) => isFixed(c))) && (
                  <>
                    <dt style={{ color: HAND_COLOR.A }}>고정하는 손</dt>
                    <dd>{handLine(step.contacts.filter((c) => isFixed(c)))}</dd>
                  </>
                )}
                <dt style={{ color: HAND_COLOR.B }}>{step.contacts.some((c) => isFixed(c)) ? '늘이는 손' : '손'}</dt>
                <dd>{handLine(step.contacts.filter((c) => !isFixed(c))) || '고정한 채 고개를 움직여 늘입니다.'}</dd>
              </dl>
              <details class="xsmall ink2">
                <summary>원본 영상 해설</summary>
                {step.narration}
              </details>
            </div>
          )}
          <div class="row between">
            <button
              class="iconbtn"
              aria-label="처음부터"
              onClick={() => {
                clock.reset();
                lastCue.current = '';
              }}
            >
              <Icon name="reset" />
            </button>
            <input
              class="range grow"
              type="range"
              min={0}
              max={Math.round(plan.total * 10)}
              value={Math.round(elapsed * 10)}
              aria-label="진행 위치"
              onInput={(e) => clock.seek(Number((e.target as HTMLInputElement).value) / 10)}
            />
            <span class="xsmall muted tabular">
              {mmss(elapsed)} / {mmss(plan.total)}
            </span>
          </div>
          <button class="btn primary block" onClick={() => (clock.running ? clock.pause() : clock.play())}>
            <Icon name={clock.running ? 'pause' : 'play'} />{' '}
            {clock.running ? '일시정지' : finished ? '다시 하기' : started ? '계속' : '따라하기 시작'}
          </button>
          {program && program.steps.length > 1 && (
            <div class="fsr-steps" role="list">
              {program.steps.map((s, i) => (
                <button class={i === scene.stepIndex ? 'on' : ''} onClick={() => clock.seek(stepStart(i) + 0.01)}>
                  <b>{i + 1}</b>
                  {s.short}
                </button>
              ))}
            </div>
          )}
          <div class="legend">
            {scene.mode === 'stretch' && scene.hands.some((h) => h.c.hand === 'A') && (
              <span>
                <i style={{ background: HAND_COLOR.A, height: '10px', width: '10px', borderRadius: '50%' }} />
                {scene.hands.some((h) => h.c.hand === 'A' && !h.c.move[0] && !h.c.move[1]) ? '손 A · 고정(자물쇠)' : '손 A'}
              </span>
            )}
            {(scene.mode === 'stretch' || scene.mode === 'massage') && (
              <span>
                <i style={{ background: HAND_COLOR.B, height: '10px', width: '10px', borderRadius: '50%' }} />손 B · 화살표 방향으로
              </span>
            )}
            {stageMode !== 'video' && (
              <span>
                <i style={{ background: '#D94848', opacity: 0.5, height: '10px', width: '16px', borderRadius: '5px' }} />
                근육 ({SIDE_LABEL[aff]} = 마비 쪽)
              </span>
            )}
          </div>
          <button class="btn sm ghost" onClick={() => setShowSettings(!showSettings)} aria-expanded={showSettings}>
            <Icon name="settings" /> 보기 설정
          </button>
          {showSettings && (
            <div class="stack small">
              <Segmented
                label="그림 방향"
                value={viewMode}
                onChange={setViewMode}
                options={[
                  { value: 'mirror', label: '거울처럼' },
                  { value: 'clinical', label: '마주 본 모습' },
                ]}
              />
              {(videoOnly
                ? []
                : ([
                    ['showMuscle', '근육 표시'],
                    ['callouts', '손 위치 설명(말풍선)'],
                    ['ghostHands', '손 반투명 (가려진 곳 보기)'],
                    ['loupe', '환측 확대 돋보기 (2D)'],
                    ['riggedHands', '3D 관절 손 (시범)'],
                  ] as const)
              ).map(([k, label]) => (
                <label class="check" style={{ padding: '4px 0' }}>
                  <input type="checkbox" checked={prefs[k]} onChange={(e) => setPref(k, (e.target as HTMLInputElement).checked)} />
                  <span>{label}</span>
                </label>
              ))}
              {program && (
                <div class="row between">
                  <span>유지 시간</span>
                  <Segmented
                    label="유지 시간"
                    value={prefs.holdSec ? String(prefs.holdSec) : 'auto'}
                    onChange={(v) => setPref('holdSec', v === 'auto' ? null : Number(v))}
                    options={[
                      // 자동 = the prescription, adjusted by earlier answers (rehab/dose.ts).
                      { value: 'auto', label: `자동 ${dose?.opts.holdSec ?? ex.holdSec ?? 10}초` },
                      ...['5', '10', '15', '20'].map((v) => ({ value: v, label: `${v}초` })),
                    ]}
                  />
                </div>
              )}
              <div class="row between">
                <span>재생 속도</span>
                <Segmented
                  label="재생 속도"
                  value={String(prefs.speed)}
                  onChange={(v) => setPref('speed', Number(v))}
                  options={['0.75', '1', '1.5'].map((v) => ({ value: v, label: `${v}x` }))}
                />
              </div>
            </div>
          )}
          {ex.reference && (
            <p class="xsmall muted">
              동작 출처: {ex.reference}
              {step && step.videoAt >= 0 && (
                <>
                  {' '}
                  ·{' '}
                  <a href={videoLink(step.videoAt)} target="_blank" rel="noopener noreferrer">
                    원본 영상 {mmss(step.videoAt)}부터 보기
                  </a>{' '}
                  · 손 위치: {step.source === 'frame-grid' ? '참고 프레임 격자 측정' : '영상 프레임 판독'}
                </>
              )}
            </p>
          )}
        </div>

        <div class="card">
          <h3>따라하는 순서</h3>
          <ol class="steps">
            {ex.steps.map((s, k) => (
              <li class={started && !finished && k === scene.textStep ? 'current' : ''}>{s}</li>
            ))}
          </ol>
        </div>

        {ex.kind === 'relax' && <BreathPacer scene={scene} running={clock.running && !finished} />}

        {ex.kind !== 'eyecare' && ex.kind !== 'relax' && (
          <div class="card">
            <div class="card-head">
              <h3>
                내 얼굴로 따라하기
                {guideKind === 'move' ? ' · 실시간 안내' : guideKind === 'stretch' || guideKind === 'massage' ? ' · 손 위치 안내' : ''}
              </h3>
              <button
                class={`btn sm ${mirror ? 'primary' : ''}`}
                onClick={() => {
                  setMirror(!mirror);
                  setCalib('none');
                  setCoach(null);
                  counter.current = null;
                  coachState.current = 'rest';
                  lastMarks.current = null;
                  setFaceLost(false);
                  refFrames.current = [];
                  synkLevel.current = 0;
                  steady.current = 0;
                  tracker.current = null;
                  trackMode.current = 'off';
                  setLiveTracking('off');
                  lastTracked.current = null;
                }}
              >
                <Icon name="mirror" /> {mirror ? '끄기' : '켜기'}
              </button>
            </div>
            {mirror && (
              <>
                <CameraStage cam={cam}>
                  <div class="hud">
                    <div class="hud-top">
                      <div class="chips">
                        {started && !finished && (
                          <span class={`chip ${scene.phase.key === 'hold' ? 'good' : ''}`}>
                            {scene.phase.label}
                            {['hold', 'prepare', 'stretch', 'release', 'rest', 'stroke'].includes(scene.phase.key)
                              ? ` ${Math.max(1, Math.ceil(scene.remaining))}`
                              : ''}
                          </span>
                        )}
                        {started && !finished && scene.reps > 1 && (
                          <span class="chip tabular">
                            {Math.max(1, scene.rep)}/{scene.reps}
                            {scene.mode === 'massage' ? '' : '회'}
                          </span>
                        )}
                        {task && calib === 'ready' && coach?.ratio != null && ratioShown && (
                          <span class="chip tabular">마비 쪽 {Math.round(coach.ratio * 100)}%</span>
                        )}
                      </div>
                      {!halfMirror && (
                        <div class="cam-pip" aria-hidden="true">
                          <RehabStage
                            ex={ex}
                            plan={plan}
                            clock={clock}
                            mode={stageMode === '3d' ? '2d' : stageMode}
                            view={view2d}
                            loupe={false}
                            onFail3D={() => undefined}
                          />
                        </div>
                      )}
                    </div>
                    {guideKind && calib !== 'ready' ? (
                      <div class="banner">
                        {calib === 'collecting'
                          ? '편안히 정면을 보세요… 기준 얼굴을 재는 중 (2초)'
                          : guideKind === 'move'
                            ? '얼굴을 화면 가운데에 두면 기준 얼굴을 자동으로 잽니다'
                            : '손을 내리고 얼굴을 가운데에 두면 기준 얼굴을 자동으로 잽니다'}
                      </div>
                    ) : task && calib === 'ready' && (coach?.synkLevel ?? 0) > 0 ? (
                      <div class={`hud-warn l${coach!.synkLevel}`} role="alert">
                        {synkText(task, coach!.synkLevel!)}
                      </div>
                    ) : (
                      <div />
                    )}
                  </div>
                </CameraStage>
                <label class="check" style={{ padding: '2px 0' }}>
                  <input
                    id="half-mirror"
                    type="checkbox"
                    checked={halfMirror}
                    onChange={(e) => setHalfMirror((e.target as HTMLInputElement).checked)}
                  />
                  <span>
                    거울 효과{' '}
                    <span class="small muted">— 건강한 쪽 얼굴을 마비 쪽에 비춰, 양쪽이 같이 움직이는 모습을 보며 운동합니다</span>
                  </span>
                </label>
                {halfMirror && (
                  <p class="xsmall muted" style={{ margin: 0 }}>
                    화면의 마비 쪽은 실제 얼굴이 아니라 건강한 쪽을 비춘 모습입니다(급성 중증 벨마비 무작위 연구 MEPP에서 1년 뒤 연합운동이
                    적었던 방법). 목표 표시는 숨기고, 막대와 횟수는 실제 마비 쪽 움직임으로 셉니다. 고개를 많이 돌리면 잠시 실제 얼굴이
                    보입니다.
                  </p>
                )}
                {guideKind === 'massage' && calib === 'ready' && (
                  <div class="stack bio-coach">
                    <p class={`coach-status ${started && !finished ? 'move' : 'rest'}`} aria-live="polite">
                      {started && !finished
                        ? scene.phase.key === 'prepare'
                          ? '주황 원에 검지·중지를 대세요'
                          : '주황 점선을 따라 작은 원을 그리며 천천히 옮기세요'
                        : '‘따라하기 시작’을 누르면 손가락을 댈 곳이 얼굴 위에 나타납니다'}
                    </p>
                    <p class="xsmall muted">주황 원: 지금 손가락이 있어야 할 곳, 점선과 화살표: 문지르며 옮겨 갈 길(마비 쪽).</p>
                    <button class="btn sm ghost" onClick={() => setCalib('none')}>
                      기준 얼굴 다시 재기
                    </button>
                  </div>
                )}
                {guideKind === 'stretch' && calib === 'ready' && (
                  <div class="stack bio-coach">
                    <p class={`coach-status ${faceLost ? 'synk' : started && !finished ? 'move' : 'rest'}`} aria-live="polite">
                      {faceLost
                        ? '손에 얼굴이 많이 가려졌어요. 손을 잠시 내렸다가 다시 대 주세요'
                        : started && !finished
                          ? stretchCue(scene)
                          : '‘따라하기 시작’을 누르면 손을 댈 곳이 얼굴 위에 나타납니다'}
                    </p>
                    <p class="xsmall muted">
                      파란 원: 고정하는 손, 주황 원과 화살표: 늘이는 손의 시작과 끝, 작은 점: 지금 손가락이 있어야 할 곳. 점선 원은 입안에
                      넣는 손가락입니다. 고개를 많이 돌리는 단계에서는 위치가 덜 정확합니다.
                    </p>
                  </div>
                )}
                {task && bioPlan && calib === 'ready' && (
                  <div class="stack bio-coach">
                    <p class={`coach-status ${coach?.state ?? 'rest'}`} aria-live="polite">
                      {cam.quality && !cam.quality.ok
                        ? '얼굴을 화면 가운데에 두고 정면을 봐 주세요'
                        : coachText(task, coach ?? { state: 'rest', progress: 0, healthyLoad: 0, held: 0, reps: 0 })}
                    </p>
                    <div class="bio">
                      <span class="small">마비 쪽</span>
                      <div class="track goal">
                        <div
                          class="fill"
                          style={{
                            width: `${Math.min(100, ((coach?.progress ?? 0) / 1.25) * 100)}%`,
                            background: coach?.state === 'good' ? 'var(--good)' : 'var(--warning)',
                          }}
                        />
                        <i class="tick" style={{ left: '80%' }} />
                      </div>
                      <span class="small tabular">{Math.round((coach?.progress ?? 0) * 100)}%</span>
                    </div>
                    <div class="bio">
                      <span class="small">건강한 쪽</span>
                      <div class="track goal">
                        <div
                          class="fill"
                          style={{
                            width: `${Math.min(100, ((coach?.healthyLoad ?? 0) / 1.5) * 100)}%`,
                            background: coach?.state === 'tooStrong' ? 'var(--critical)' : 'var(--series-3)',
                          }}
                        />
                        <i class="tick" style={{ left: `${100 / 1.5}%` }} />
                      </div>
                      <span class="small tabular">{SIDE_LABEL[healthy]}</span>
                    </div>
                    <div class="bio">
                      <span class="small">{STILL_NAME[offTargetRegion(task)]}(그대로)</span>
                      <div class="track">
                        <div
                          class="fill"
                          style={{
                            width: `${Math.min(100, ((coach?.synkIndex ?? 0) / synkCuts(task)[2]) * 100)}%`,
                            background: coach?.synkLevel ? `rgb(${STILL_RGB[coach.synkLevel].join(',')})` : 'var(--good)',
                          }}
                        />
                      </div>
                      <span class="small">{SYNK_GRADE[coach?.synkLevel ?? 0]}</span>
                    </div>
                    <div class="row between small">
                      <span class="ink2">지금 마비 쪽 움직임</span>
                      <b class="tabular">
                        {!ratioShown
                          ? '이 폰에서는 보여 주지 않아요'
                          : coach?.ratio != null
                            ? `건강한 쪽의 ${Math.round(coach.ratio * 100)}%`
                            : '건강한 쪽이 움직이면 보여요'}
                      </b>
                    </div>
                    <div class="row between small">
                      <span class="ink2">잘한 횟수 (목표를 1초 유지)</span>
                      <b class="tabular">{coach?.reps ?? 0}회</b>
                    </div>
                    <p class="xsmall muted">
                      {goalText(bioPlan)} 노란 점선이 목표, 흰 선이 처음 위치, 흐린 점선은 건강한 쪽이 넘지 않을 선입니다.{' '}
                      {STILL_NAME[offTargetRegion(task)]}가 같이 움직이면 그 자리가 주황(약함)에서 빨강(중간), 짙은 빨강(강함)으로
                      표시됩니다.
                    </p>
                    <button class="btn sm ghost" onClick={() => setCalib('none')}>
                      기준 얼굴 다시 재기
                    </button>
                  </div>
                )}
              </>
            )}
            {!mirror && (
              <p class="small muted">
                {videoOnly ? '시연 영상' : '그림'}과 함께 전면 카메라를 거울처럼 볼 수 있습니다. 켜면 기준 얼굴을 자동으로 재고, 얼굴 위에
                {guideKind === 'move' ? ' 목표와 움직이면 안 되는 곳을' : guideKind ? ' 손 댈 곳을' : ''} 보여 줍니다. 영상은 저장되지
                않습니다.
              </p>
            )}
          </div>
        )}

        <div class="card warn tight">
          {ex.cautions.map((c) => (
            <Notice tone="warn">
              <span class="small">{c}</span>
            </Notice>
          ))}
          <Notice tone="warn">
            <span class="small">통증, 눈 자극, 어지러움이 생기면 즉시 중단하세요.</span>
          </Notice>
        </div>

        {routine ? (
          !finished && (
            <button class="btn block" onClick={goNext}>
              이 운동 건너뛰기 <Icon name="chev" />
            </button>
          )
        ) : saved && logId ? (
          <div class="card accent">
            <h3>기록했습니다</h3>
            <QualityLine q={quality} />
            <FeelPrompt logId={logId} onAnswered={() => setTimeout(() => navigate('/rehab'), 700)} />
            <button class="btn ghost block" style={{ marginTop: '8px' }} onClick={() => navigate('/rehab')}>
              답하지 않고 돌아가기
            </button>
          </div>
        ) : (
          <button class="btn primary block" onClick={complete} disabled={saved}>
            <Icon name="check" /> {saved ? '기록했습니다' : '오늘 완료로 기록'}
          </button>
        )}
      </main>
    </>
  );
}
